enum SheetRoute: Identifiable {
    case help
    case edit(id: Int)

    var id: String {
        switch self {
        case .help: return "help"
        case .edit(let id): return "edit_\(id)"
        }
    }
}

let route: SheetRoute = .edit(id: 42)
print("Route: \(route.id)")

struct ModalManager {
    var currentItem: String? = nil

    mutating func select(_ item: String) {
        currentItem = item
    }

    mutating func clear() {
        currentItem = nil
    }
}

var manager = ModalManager()
manager.select("Document")
print("Selected: \(manager.currentItem ?? "none")")
manager.clear()
print("Cleared: \(manager.currentItem ?? "none")")

struct AlertState {
    var title: String
    var message: String
    var isDestructive: Bool
}

struct DeletePrompt {
    var targetFile: String?

    func createAlert() -> AlertState? {
        guard let file = targetFile else {
            return nil
        }
        return AlertState(title: "Delete \(file)", message: "Cannot be undone", isDestructive: true)
    }
}

let prompt = DeletePrompt(targetFile: "data.csv")
if let alert = prompt.createAlert() {
    print("Alert: \(alert.title), Destructive: \(alert.isDestructive)")
}

enum SheetHeight {
    case medium
    case large
}

struct DetentTracker {
    var allowedHeights: [SheetHeight] = [.medium, .large]
    var selectedHeight: SheetHeight = .medium

    mutating func expand() {
        selectedHeight = .large
    }
}

var tracker = DetentTracker()
tracker.expand()
print("Height: \(tracker.selectedHeight), Count: \(tracker.allowedHeights.count)")

struct DraftEditor {
    var content: String = ""
    var isModified: Bool = false

    var isDismissDisabled: Bool {
        return isModified && !content.isEmpty
    }
}

var editor = DraftEditor(content: "Unsaved text", isModified: true)
print("Dismiss disabled: \(editor.isDismissDisabled)")

enum DialogAction: String {
    case share = "Share"
    case duplicate = "Duplicate"
    case delete = "Delete"
}

struct DialogConfig {
    let actions: [DialogAction] = [.share, .duplicate, .delete]

    func actionCount() -> Int {
        return actions.count
    }
}

let config = DialogConfig()
print("Actions: \(config.actionCount())")

struct DismissCallback {
    var onDismiss: () -> Void

    func close() {
        onDismiss()
    }
}

var closed = false
let handler = DismissCallback { closed = true }
handler.close()
print("Closed: \(closed)")

struct AlertActionItem {
    var id: String
    var title: String
    var role: String
}

let action = AlertActionItem(id: "cancel_btn", title: "Cancel", role: "cancel")
print("Action: \(action.title), Role: \(action.role)")

