import Foundation

enum AppSheet: Identifiable {
    case settings
    case profile(username: String)

    var id: String {
        switch self {
        case .settings:
            return "settings"
        case .profile(let username):
            return "profile_\(username)"
        }
    }
}

let sheet = AppSheet.profile(username: "alex")
print("Sheet: \(sheet.id)")

import Foundation

struct SheetCoordinator {
    var activeSheet: String? = nil

    mutating func present(name: String) {
        activeSheet = name
    }

    mutating func dismiss() {
        activeSheet = nil
    }
}

var coordinator = SheetCoordinator()
coordinator.present(name: "helpModal")
print("Active: \(coordinator.activeSheet ?? "none")")
coordinator.dismiss()
print("After: \(coordinator.activeSheet ?? "none")")

import Foundation

struct FormEditor {
    var text: String = ""
    var isSaved: Bool = false

    var canDismiss: Bool {
        return isSaved || text.isEmpty
    }
}

var editor1 = FormEditor(text: "Hello", isSaved: false)
var editor2 = FormEditor(text: "Hello", isSaved: true)
print("Can dismiss 1: \(editor1.canDismiss), 2: \(editor2.canDismiss)")
